// Generates the Claude Code agent files from the Grok project, so there is one source for every prompt.
//
//   node scripts/build-claude-agents.mjs          writes <repo>/.claude/agents/*.md
//   node scripts/build-claude-agents.mjs --check  exits 1 if the files on disk differ from what would be written
//
// Sources: bot/instructions.md, bot/subagents/<id>/{agent.ts,instructions.md}.
// Do not edit the generated files; edit the sources and rerun.

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(here, "..");
const outDir = resolve(projectRoot, "..", ".claude", "agents");
const check = process.argv.includes("--check");

const PREFIX = "mcp__governance__";
const READ = ["Read", "Grep", "Glob"];
const RANK = ["haiku", "sonnet", "opus", "fable"];
const ORCHESTRATOR_MODEL = "sonnet";
const stagesJson = JSON.parse(readFileSync(join(projectRoot, "journey", "stages.json"), "utf8")).stages;
// A subagent's default is the strongest model any of its stages asks for, so a missed override is never too weak.
// The orchestrator passes the stage's own model when it delegates, which is how a cheaper model is used per request.
const modelFor = (id) => stagesJson.filter((s) => s.subagent === id).map((s) => s.model).filter(Boolean).sort((a, b) => RANK.indexOf(b) - RANK.indexOf(a))[0] ?? "sonnet";

// Least privilege per subagent. Only the orchestrator may report stages or file approvals.
// One subagent per stage (no subagent spans more than one stage).
const SUBAGENT_TOOLS = {
  "stage-intent": { run: true, write: true },
  "stage-hypothesis": { run: true, write: true },
  "stage-benefit": { run: true, write: true },
  "stage-objective": { run: true, write: true },
  "stage-pillars": { run: true, write: true },
  "stage-requirement": { run: true, write: true },
  "stage-project": { run: true, write: false },
  "stage-readiness": { run: true, write: false },
  "stage-deliverable": { run: true, write: false },
  "stage-verification": { run: true, write: false },
  "stage-audit": { run: false, write: true },
  "stage-outcome": { run: false, write: true },
  "stage-observation": { run: false, write: true },
  "stage-insight": { run: false, write: true },
  "stage-lesson": { run: false, write: true },
  "stage-governance": { run: true, write: true },
  "stage-adaptation": { run: true, write: true },
  "stage-refinement": { run: true, write: true },
};

const NOTE = `> Claude Code note: the governance tools appear with the prefix \`${PREFIX}\`, for example \`${PREFIX}journey_status\`. Wherever these instructions name a tool without the prefix, use the prefixed one.`;
const HEADER = (src) => `<!-- Generated by governance-orchestrator/scripts/build-claude-agents.mjs from ${src}. Do not edit; edit the source and rerun. -->`;

const descriptionOf = (agentTs) => {
  const m = readFileSync(agentTs, "utf8").match(/description:\s*"((?:[^"\\]|\\.)*)"/s);
  if (!m) throw new Error(`No description in ${agentTs}`);
  return JSON.parse(`"${m[1]}"`);
};

const frontmatter = (name, description, tools, model) =>
  `---\nname: ${name}\ndescription: ${JSON.stringify(description)}\ntools: ${tools.join(", ")}\nmodel: ${model}\n---\n`;

const files = new Map();

// Subagents
const subDir = join(projectRoot, "bot", "subagents");
const subs = readdirSync(subDir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
for (const id of subs) {
  const policy = SUBAGENT_TOOLS[id];
  if (!policy) throw new Error(`No tool policy for subagent ${id}: add it to SUBAGENT_TOOLS`);
  const tools = [...READ];
  if (policy.run) tools.push(`${PREFIX}run_command`);
  if (policy.write) tools.push(`${PREFIX}write_document`);
  const body = readFileSync(join(subDir, id, "instructions.md"), "utf8").trim();
  const src = `bot/subagents/${id}/`;
  files.set(`${id}.md`, `${frontmatter(id, descriptionOf(join(subDir, id, "agent.ts")), tools, modelFor(id))}\n${HEADER(src)}\n\n${NOTE}\n\n${body}\n`);
}
for (const id of Object.keys(SUBAGENT_TOOLS)) if (!subs.includes(id)) throw new Error(`SUBAGENT_TOOLS names ${id} but bot/subagents/${id}/ does not exist`);

// Orchestrator (runs as the main session: claude --agent governance-orchestrator)
let main = readFileSync(join(projectRoot, "bot", "instructions.md"), "utf8");
main = main.replace(/\n## Memory[\s\S]*$/, "\n").trim();
const orchTools = [
  `Agent(${subs.join(", ")})`,
  ...READ,
  ...["journey_status", "check_approvals", "check_reuse", "report_stage", "request_approval", "notify", "run_command"].map((t) => PREFIX + t),
];
files.set(
  "governance-orchestrator.md",
  `${frontmatter("governance-orchestrator", "Runs the 18-stage Intent-to-Outcome governance loop: delegates each stage to a stage subagent, records reports, files approval requests for the human, and never approves. Start it with: claude --agent governance-orchestrator", orchTools, ORCHESTRATOR_MODEL)}\n${HEADER("bot/instructions.md")}\n\n${NOTE}\n\n${main}\n`,
);

let changed = 0;
mkdirSync(outDir, { recursive: true });
for (const [name, content] of files) {
  const path = join(outDir, name);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  changed++;
  if (!check) writeFileSync(path, content);
}
console.log(check ? (changed ? `${changed} file(s) out of date` : "up to date") : `wrote ${files.size} agent files to ${outDir} (${changed} changed)`);
if (check && changed) process.exit(1);
